{
  "units": [
    {
      "quote": "The term “applicant” is used hereinafter for the individual whose citizenship and identity is being adjudicated, including for form DS-2060.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "The term \"applicant\" is defined as the individual whose citizenship and identity is being adjudicated, which includes individuals being adjudicated for form DS-2060."
    },
    {
      "quote": "For purposes of this chapter, minor applicants are defined as un-emancipated applicants under the age of 18.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "For the purposes of this chapter, minor applicants are defined as un-emancipated applicants who are under 18 years of age."
    },
    {
      "quote": "A material discrepancy is any name change that is not defined as immaterial in 8 FAM 403.1-5.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "A material discrepancy is defined as any name change that is not classified as immaterial under 8 FAM 403.1-5."
    },
    {
      "quote": "The applicant must explain any material discrepancies between the name on the application and the name recorded in the evidence of U.S. citizenship/non-citizen U.S. nationality and the evidence of identity (see 22 CFR 51.25).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The applicant is required to explain any material discrepancies between the name provided on the application and the name appearing on their evidence of U.S. citizenship/non-citizen U.S. nationality and evidence of identity."
    },
    {
      "quote": "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section (see an exception for married names in 8 FAM 403.1-4(C)).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Subject to an exception for married names in 8 FAM 403.1-4(C), any material discrepancies between the name on the application, the citizenship/non-citizen nationality evidence, or identity evidence must be documented by submitting one or more of the acceptable documents listed in 8 FAM 403.1-4(b)."
    },
    {
      "quote": "Court orders or decrees:\n\n(a) Name change orders; or\n\n(b) Divorce decrees;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "An acceptable means of documenting a material name change includes court orders or decrees, specifically name change orders or divorce decrees."
    },
    {
      "quote": "Certificates of naturalization;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "An acceptable means of documenting a material name change includes certificates of naturalization."
    },
    {
      "quote": "Marriage certificates;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "An acceptable means of documenting a material name change includes marriage certificates."
    },
    {
      "quote": "Documentation demonstrating change of name by operation of state law;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "An acceptable means of documenting a material name change includes documentation demonstrating that a name change occurred by operation of state law."
    },
    {
      "quote": "Documentation of customary usage.",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "An acceptable means of documenting a material name change includes documentation demonstrating customary usage."
    },
    {
      "quote": "Evidence of material name changes must be reviewed for evidence of counterfeiting or alteration (see 8 FAM 201.1)",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Personnel are required to review evidence submitted for material name changes for any signs of counterfeiting or alteration."
    },
    {
      "quote": "The applicant may not continue to use a previous name after a material name change unless the name change documentation specifically permits the applicant to continue using that name (see 8 FAM 403.1-6 regarding “known as” names).",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "An applicant is prohibited from continuing to use a previous name following a material name change, unless the name change documentation explicitly authorizes the applicant to continue using that name."
    },
    {
      "quote": "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:",
      "scope_quotes": [
        "The applicant's name is an integral part of her/his identity. Consequently,"
      ],
      "kind": "condition",
      "meaning": "Evidence of identity may be required pursuant to 22 CFR 51.23(c) and Department guidance in order to establish the name that best identifies the applicant."
    },
    {
      "quote": "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name.",
      "scope_quotes": [
        "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"
      ],
      "kind": "requirement",
      "meaning": "If an applicant underwent a material name change more than one year before submitting form DS-11 and has not updated their identification to reflect the change, adjudicators must suspend the application and request an acceptable ID in the applicant's new name."
    },
    {
      "quote": "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;",
      "scope_quotes": [
        "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."
      ],
      "kind": "permission",
      "meaning": "When an applicant with an un-updated ID after a material name change over a year prior faces urgent or emergency travel and there is insufficient time to request an acceptable ID, a limited-validity passport is permitted to be issued in the requested name."
    },
    {
      "quote": "The applicant generally will need the name change documentation to change the name on her/his ID.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "The applicant will generally require their name change documentation in order to effectuate a name change on their identification."
    },
    {
      "quote": "You must fully notate the name change documentation prior to returning the documentation, including that the documentation was \"seen and returned,\" to the applicant with the information request letter (IRL);",
      "scope_quotes": [
        "The applicant generally will need the name change documentation to change the name on her/his ID."
      ],
      "kind": "requirement",
      "meaning": "Adjudicators are required to fully notate the applicant's name change documentation, including recording that it was 'seen and returned,' before sending it back to the applicant with an Information Request Letter (IRL)."
    },
    {
      "quote": "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name.",
      "scope_quotes": [],
      "kind": "exemption",
      "meaning": "Applicants who underwent a material name change within one year prior to applying on form DS-11 are exempt from having to submit identification in their new name."
    },
    {
      "quote": "However, if the ID has not yet been changed, they must submit their name change documentation.",
      "scope_quotes": [
        "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
      ],
      "kind": "requirement",
      "meaning": "If an applicant whose material name change occurred within one year of applying on form DS-11 has not yet changed their ID, they are required to submit their name change documentation."
    },
    {
      "quote": "The court order or decree must be final:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Any court order or decree relied upon for a name change is required to be final."
    }
  ]
}

